function setMapView(overview=false,{instant=false}={}){japanOverview=overview;$('#selection').hidden=selected<0||overview||!visibleCamps().length;$('#mapPins').classList.toggle('overview',overview);$('#japanView').classList.toggle('selected',overview);$('#areaView').classList.toggle('selected',!overview);yaw=0;pitch=MAP_PITCH;let position=camTarget.clone(),distance=dist;if(overview){position.set(-28,0,-22);distance=395;}else{const list=visibleCamps();if(list.length){const xs=list.map(c=>c.pin[0]),zs=list.map(c=>c.pin[2]),width=Math.max(...xs)-Math.min(...xs),height=Math.max(...zs)-Math.min(...zs);distance=Math.max(selectedPrefs.length?49:selectedRegions.length?88:128,(height+14)/.58,(width+22)/(.55*innerWidth/innerHeight));position.set((Math.min(...xs)+Math.max(...xs))/2-(innerWidth<600?1:6),0,(Math.min(...zs)+Math.max(...zs))/2+2);}else{const bounds=selectedPrefs.length?selectedPrefs.map(p=>areaBounds(regionForPrefecture(p),p,camps)):selectedRegions.map(r=>areaBounds(r));const valid=bounds.filter(Boolean);if(valid.length){const w=Math.min(...valid.map(b=>b[0])),so=Math.min(...valid.map(b=>b[1])),e=Math.max(...valid.map(b=>b[2])),n=Math.max(...valid.map(b=>b[3])),[x,z]=geoPoint((w+e)/2,(so+n)/2);position.set(x,0,z);distance=Math.max(75,(e-w)*24,(n-so)*24);}}}$('#mapCaption').textContent=visibleCamps().length+'か所を表示 ・ ドラッグで移動';moveMapTo(position,distance,{instant});lastPinLayout=0;}


function activityIcons(c){return actions.filter(a=>did(c,a[0])).map(a=>`<span title="${a[2]}：体験済み">${a[1]}</span>`).join('')}
function mapPinMarkup(c,i){return `<button aria-label="${c.name} ${visits(c).length}回訪問 ${actions.filter(a=>did(c,a[0])).map(a=>a[2]+'体験済み').join(' ')}" class="pin ${selected===i?'selected':''}" data-pin="${i}"><span class="pinName">${c.short}</span><span class="pinActivities">${activityIcons(c)}</span>${visits(c).length?`<em>✓ ${visits(c).length}回</em>`:''}</button>`}

function makeMapMiniature(c){const [x,,z]=c.pin;const miniature=group(x,.02,z);mapMiniatures.set(c.id,miniature);const patch=cyl(1.55,1.7,.18,c.color,0,.04,0,miniature,10);patch.userData.layer=-2;tree(-1.1,-.65,.35,c.land==='forest'?0:1,miniature);const summary=activitySummary(saved[c.id].visits);if(summary.tent)shelter(-.4,0,.72,miniature,latestShelter(c));if(summary.fire){const fire=miniFire(.85,.15,miniature);fire.scale.setScalar(1.25)}if(summary.meal)miniMeal(.2,1.05,miniature);if(summary.car){const mini=makeCar(miniature);mini.position.set(.95,0,-.7);mini.scale.setScalar(.25)}if(summary.tarp){const mini=makeTarp(miniature);mini.position.set(-.6,0,-.65);mini.scale.setScalar(.3)}if(summary.sleep){box(.75,.12,.45,0x799c91,-.75,.2,1.05,miniature);const zzz=textSprite('z Z','#547562',.3,miniature);zzz.position.set(-.75,.7,1.05)}if(['river','genshi','highlake'].includes(c.land)){const water=cyl(.6,.65,.03,0x94c4be,.9,.15,-.5,miniature,12);water.scale.z=.5}miniature.visible=false;return miniature;}
function makeMap(){camera=mapCamera;clearWorld();mapMiniatures.clear();scene.background.set(0xdce9e5);scene.fog.color.copy(scene.background);scene.fog.near=280;scene.fog.far=800;japanLand();const decorationStart=root.children.length;const [fx,fz]=geoPoint(138.73,35.36);fuji(fx,fz,.14);for(const [lon,lat] of [[137.8,36],[137.8,36.6],[138.2,36.9],[139.2,37.2],[140.6,38.4],[140.8,39.1],[135.8,35.2]]){const [x,z]=geoPoint(lon,lat);cone(1.4,2.2,0x92ad82,x,1.1,z,root,6)}for(const [name,lon,lat] of [['北海道',142.8,43.8],['本州',136.5,35.4],['四国',133.5,33.8],['九州',130.9,32.7]]){const [x,z]=geoPoint(lon,lat),t=textSprite(name,'#718970',1.6);t.position.set(x,.5,z)}const decoration=group();decoration.name='map-scenery';for(const object of root.children.slice(decorationStart)){if(object!==decoration)decoration.add(object);}$('#mapPins').innerHTML=camps.map(mapPinMarkup).join('');document.querySelectorAll('[data-pin]').forEach(b=>b.onclick=e=>{if(e.detail===0)selectCamp(+b.dataset.pin)});updateMap();setMapView(japanOverview,{instant:true});restoreMapView();dist=wantedDist;updateMapCamera(mapCamera,{target:camTarget,distance:dist,aspect:innerWidth/innerHeight})}
function layoutPins(){
 camera.updateMatrixWorld();const scenery=root.getObjectByName('map-scenery');if(scenery)scenery.visible=dist>35;mapNamesVisible=showMapNames(dist,mapNamesVisible);const pins=$('#mapPins');pins.classList.toggle('named',mapNamesVisible);pins.classList.remove('clustered');pins.classList.toggle('simple',dist>42);$('#mapClusters').hidden=true;
 const top=$('#mapUI').getBoundingClientRect().top,points=[],unit=(mapCamera.top-mapCamera.bottom)/innerHeight;
 for(const el of pins.children){const c=camps[+el.dataset.pin];if(!c||el.hidden)continue;const v=new THREE.Vector3(c.pin[0],.02,c.pin[2]).project(camera),x=(v.x*.5+.5)*innerWidth,y=(-v.y*.5+.5)*innerHeight-top;if(v.z>-1&&v.z<1&&x>-70&&x<innerWidth+70&&y>-70&&y<innerHeight-top+70)points.push({id:c.id,x,y,el,c,priority:+el.dataset.pin===selected?1:0});}
 const slots=progressiveSlots(points,22),miniSlots=progressiveSlots(points,48),names=visibleNameSlots(points.filter(p=>slots.has(p.id)),innerWidth<600?104:128,42);
 for(const el of pins.children)el.style.visibility='hidden';for(const miniature of mapMiniatures.values())miniature.visible=false;
 for(const p of points){if(!slots.has(p.id))continue;p.el.style.visibility='visible';p.el.style.left=p.x+'px';p.el.style.top=p.y+'px';p.el.classList.toggle('labelSuppressed',!names.has(p.id));if(dist<=42&&miniSlots.has(p.id)){const miniature=mapMiniatures.get(p.id)||makeMapMiniature(p.c);miniature.visible=true;miniature.scale.setScalar(Math.min(.62,42*unit/3.4)*Math.min(1,(42-dist)/10));}}
 mapDirty=true;
}




function updateMap(){mapFrameKey='';mapDirty=true;const matches=visibleCamps();if(!matches.includes(camps[selected]))selected=-1;const c=camps[selected];renderRegionFilters();renderAttributeButtons();$('#filterSummary').textContent=activeAttributes.length?activeAttributes.join('・'):'複数選択可・選んだ条件すべてに一致';$('#filterCount').textContent=matches.length+'か所';$('#wishlistOnly').setAttribute('aria-pressed',String(wishOnly));$('#wishlistOnly').textContent=wishOnly?'♥ 行きたい場所のみ':'♡ 行きたい場所で絞る';$('#clearFilters').hidden=!activeAttributes.length&&!selectedPrefs.length&&!selectedRegions.length&&!wishOnly;$('#campList').innerHTML=matches.length?camps.map((v,i)=>{if(!matches.includes(v))return '';return `<button class="campRow ${i===selected?'selected':''}" data-camp="${i}"><span class="campTitle">${saved[v.id].wishlist?'♡ ':''}${v.short}<small>${v.region} ${visits(v).length?'・'+visits(v).length+'回訪問':''}</small><span class="rowAttributes">${v.attributes.slice(0,3).join(' / ')}</span><span class="rowBadges">${badges(v)}</span></span><span class="check">${count(v)>0?'✓':'⌖'}</span></button>`}).join(''):`<div class="emptyCamps"><b>${camps.some(c=>matchesAreas(c,selectedRegions,selectedPrefs))?'ぴったりの場所が見つかりません。':'このエリアのサンプルは準備中です。'}</b><p>条件を減らすか、ほかのエリアから探そう。</p><button id="emptyReset">絞り込みをリセット</button></div>`;if($('#emptyReset'))$('#emptyReset').onclick=clearFilters;document.querySelectorAll('[data-camp]').forEach(b=>b.onclick=()=>selectCamp(+b.dataset.camp));$('#selection').hidden=!c||!matches.length||japanOverview;if(!c)$('#selection').innerHTML='';if(c){const pending=saved._active?.campId===c.id?saved[c.id].visits.find(v=>v.id===saved._active.visitId&&!v.closed):null;$('#selection').hidden=!matches.length||japanOverview;$('#selection').innerHTML=`<div class="selectionOverview"><div><small>${c.pref} ・ ${visits(c).length}回訪問${count(c)?' ・ ✓ クリア':''}</small><h2>${c.short}</h2></div><button id="toggleWishlist" class="wishlistToggle" aria-pressed="${!!saved[c.id].wishlist}">${saved[c.id].wishlist?'♥ 行きたい':'♡ 行きたい'}</button><button id="closeMapSelection" aria-label="キャンプ場の選択を解除">×</button></div><div class="campStartSetup"></div><div class="selectionActions"><button class="primary" id="enterCamp">この設定でキャンプへ →</button>${pending?'<button class="secondary" id="resumeCamp">再開</button>':''}<button class="secondary" id="showCampDetails">詳細・履歴</button></div>`;renderStartSetup(c,$('#selection .campStartSetup'));$('#toggleWishlist').onclick=()=>toggleWishlist(c);$('#enterCamp').onclick=()=>enterCamp(false);if($('#resumeCamp'))$('#resumeCamp').onclick=()=>enterCamp(true);$('#showCampDetails').onclick=()=>showCampDetails(selected);$('#closeMapSelection').onclick=()=>{selected=-1;mapTransition=null;wantedDist=dist;syncZoom();updateMap()};}document.querySelectorAll('.pin').forEach((b,i)=>{b.classList.toggle('selected',selected===i);b.classList.toggle('wanted',!!saved[camps[i].id].wishlist);b.querySelector('.pinName').textContent=(saved[camps[i].id].wishlist?'♡ ':'')+camps[i].short;b.hidden=!matches.includes(camps[i]);(()=>{const miniature=mapMiniatures.get(camps[i].id);if(miniature)miniature.visible=matches.includes(camps[i])})()});$('#navCount').textContent=camps.filter(c=>count(c)>0).length+'/'+camps.length;$('#mapCaption').textContent=matches.length+'か所を表示 ・ ドラッグで移動';updateAreaHighlight();requestAnimationFrame(updateListScroll);lastPinLayout=0}
function showCampDetails(i){const c=camps[i],history=sortVisits(visits(c)).reverse();showModal(`<div class="eyebrow">${c.pref} / ${c.en}</div><h2>${c.name}</h2><p>${c.desc}</p><div class="tags campAttributes">${c.attributes.map(t=>`<span>${t}</span>`).join('')}</div><div class="selectionBadges">${badges(c)}<span>${visits(c).length}回訪問 ・ 体験 ${count(c)} / ${actions.length}</span></div><div class="campStartSetup" id="detailTripSetup"></div><button class="primary" id="detailEnterCamp">この設定でキャンプへ →</button><div class="pastVisitBox"><label for="pastVisitSelect">過去のキャンプの様子</label><select id="pastVisitSelect" ${history.length?'':'disabled'}>${history.length?history.map(v=>`<option value="${v.id}">${visitOption(v)}</option>`).join(''):'<option>まだ記録がありません</option>'}</select><button class="secondary" id="viewPastCamp" ${history.length?'':'disabled'}>この思い出を3Dで見る</button><div class="recordLinks"><button id="addPastCamp">＋ 過去のキャンプを登録</button><button id="editHistory">訪問日・履歴を編集</button></div></div><p class="fineprint">属性は場内・周辺の特徴です。詳細な利用条件は公式案内で確認してください。</p>`);renderStartSetup(c,$('#detailTripSetup'));$('#detailEnterCamp').onclick=()=>{$('#modal').close();enterCamp(false)};$('#viewPastCamp').onclick=()=>openPastVisit(c.id,$('#pastVisitSelect').value);$('#addPastCamp').onclick=()=>showVisitForm(c.id);$('#editHistory').onclick=()=>showHistory(i);}
function clearFilters(){activeAttributes=[];selectedRegions=[];selectedPrefs=[];wishOnly=false;$('#campList').scrollTop=0;updateMap();setMapView(false)}
function showAttributeFilters(){let draft=[...activeAttributes];showModal(`<div class="eyebrow">FIND YOUR CAMP</div><h2>どんな場所に行こう？</h2><p>県と属性を組み合わせて探せます。複数選ぶと、すべての属性を持つキャンプ場に絞ります。</p><div class="attributeChoices">${ATTRIBUTE_LABELS.map(a=>`<label><input type="checkbox" name="attribute" value="${a}" ${draft.includes(a)?'checked':''}><span>${a}</span></label>`).join('')}</div><p id="attributeMatchCount" class="filterMatch" aria-live="polite"></p><div class="formButtons"><button class="secondary" id="resetAttributes">属性をクリア</button><button class="primary" id="applyAttributes">この条件で探す →</button></div><p class="fineprint">「海」は海に近い立地を含みます。「川・釣り・遊具」は敷地内や隣接公園などの特徴です。予約条件や営業状況は施設公式でご確認ください。</p>`);const update=()=>{draft=[...document.querySelectorAll('input[name="attribute"]:checked')].map(el=>el.value);$('#attributeMatchCount').textContent=`${selectedPrefs.join('・')||selectedRegions.join('・')||'全エリア'}で ${camps.filter(c=>matchesAreas(c,selectedRegions,selectedPrefs)&&matchesCamp(c,'すべて',draft)).length}か所が見つかりました`};document.querySelectorAll('input[name="attribute"]').forEach(input=>input.onchange=update);$('#resetAttributes').onclick=()=>{document.querySelectorAll('input[name="attribute"]').forEach(input=>input.checked=false);update()};$('#applyAttributes').onclick=()=>{activeAttributes=draft;$('#modal').close();$('#campList').scrollTop=0;updateMap();setMapView(false)};update()}
function selectCamp(i){setMapMenu(false);selected=i;japanOverview=false;if(!matchesAreas(camps[i],selectedRegions,selectedPrefs)){selectedRegions=[];selectedPrefs=[];}if(wishOnly&&!saved[camps[i].id].wishlist)wishOnly=false;$('#mapPins').classList.remove('overview');$('#japanView').classList.remove('selected');$('#areaView').classList.add('selected');updateMap();const c=camps[i];moveMapTo([c.pin[0],0,c.pin[2]],Math.min(dist,innerWidth<600?78:65));lastPinLayout=0;}

function shelter(x,z,s=1,p=root,type='dome'){if(type==='ridge')return tent(x,z,s,p);if(type==='cottage')return cabin(x,z,s,p);const g=group(x,0,z,p);if(type==='pole'){cone(1.15,2.2,0xdcb980,0,1.1,0,g,12);rod([0,0,0],[0,2.3,0],.035,0x8c7656,g);const d=new THREE.BufferGeometry();d.setAttribute('position',new THREE.Float32BufferAttribute([-.45,.02,1.07,.45,.02,1.07,0,1.15,.58],3));d.computeVertexNormals();const door=mesh(d,0x526c59,0,0,0,g);door.material=new THREE.MeshStandardMaterial({color:0x526c59,side:THREE.DoubleSide});for(let i=0;i<6;i++){const a=i/6*Math.PI*2;rod([Math.cos(a),.15,Math.sin(a)],[Math.cos(a)*1.5,0,Math.sin(a)*1.5],.014,0xf2e0bb,g)}}else{const dome=mesh(new THREE.SphereGeometry(1.15,16,8,0,Math.PI*2,0,Math.PI/2),0xd99b69,0,.04,0,g);dome.scale.set(1,1,1.12);const door=ball(.55,0x526b59,0,.27,1.08,g,12);door.scale.set(.8,.9,.08);for(const a of [0,Math.PI/2]){const points=[];for(let i=0;i<=24;i++){const q=i/24*Math.PI;points.push(new THREE.Vector3(Math.cos(q)*1.17*Math.cos(a),Math.sin(q)*1.17+.05,Math.cos(q)*1.3*Math.sin(a)))}const curve=new THREE.CatmullRomCurve3(points);mesh(new THREE.TubeGeometry(curve,24,.025,5,false),0xf8dbab,0,0,0,g)}}g.scale.setScalar(s);return g}
function shelterArt(type){const drawings={dome:'<path d="M18 72A42 42 0 0 1 102 72Z" fill="#dea46e"/><path d="M45 72V57a15 15 0 0 1 30 0v15" fill="#55715f"/><path d="M60 30Q35 48 30 72M60 30Q85 48 90 72" fill="none" stroke="#f4d8ad" stroke-width="3"/>',pole:'<path d="M14 74L60 14l46 60Z" fill="#d9be8d"/><path d="M47 74l13-29 13 29Z" fill="#55715f"/><path d="M60 14v-7" stroke="#826c52" stroke-width="3"/>',ridge:'<path d="M14 72L48 20l43 8 22 44Z" fill="#c38b5d"/><path d="M14 72L48 20l36 52Z" fill="#e0a36c"/><path d="M34 72l14-29 16 29Z" fill="#55715f"/>',cottage:'<path d="M23 40h74v35H23Z" fill="#c89f70"/><path d="M12 42L60 13l48 29Z" fill="#5b7565"/><path d="M48 75V48h22v27" fill="#7f7259"/><path d="M29 49h13v13H29ZM78 49h13v13H78Z" fill="#dae4be"/>'};return `<svg viewBox="0 0 120 90" aria-hidden="true">${drawings[type]}<path d="M7 76h106" stroke="#adb990" stroke-width="3" stroke-linecap="round"/></svg>`}
function chooseShelter(){if(busy||viewingPast)return;setCampPanel('actions');document.body.dataset.actionChoice='tent';$('#campPanelTitle').textContent='テントの種類';$('#activityChoices').hidden=false;$('#activityChoices').innerHTML=`<button class="choiceBack" id="backToActivities">← 体験一覧</button><div class="activityChoiceGrid shelterChoices">${orderedShelters().map(([id,name])=>`<button data-shelter="${id}">${shelterArt(id)}<strong>${name}</strong></button>`).join('')}</div>`;$('#backToActivities').onclick=closeActivityChoice;document.querySelectorAll('[data-shelter]').forEach(b=>b.onclick=()=>doAction('tent',b.dataset.shelter));}

function makeBear(type='bear'){const c=CHARACTERS[type]||CHARACTERS.bear,g=group(.7,0,9.5);g.scale.setScalar(1.25);ball(.35,c.shirt,0,.55,0,g);ball(.38,c.body,0,1.05,0,g);for(const a of [-1,1]){if(type==='rabbit'){const ear=ball(.13,c.body,a*.2,1.55,0,g);ear.scale.set(.8,2.4,.8);const inner=ball(.07,0xd7afa2,a*.2,1.57,.08,g);inner.scale.y=2.4}else if(type==='fox'){cone(.17,.42,c.body,a*.27,1.43,0,g,4)}else{ball(.14,type==='panda'?0x47554d:c.body,a*.29,1.32,0,g)}ball(.11,type==='panda'?0x47554d:c.body,a*.2,.12,.08,g);const arm=ball(.12,c.body,a*.4,.6,.02,g);(g.userData.arms ||= []).push(arm);if(type==='panda'){const patch=ball(.09,0x47554d,a*.14,1.09,.31,g);patch.scale.z=.4}ball(.033,0x34483a,a*.13,1.09,.36,g,8);ball(.07,0xe9bb9e,a*.23,.98,.29,g)}ball(.14,0xf0dfc4,0,.95,.34,g);ball(.045,0x44503c,0,1,.46,g);if(type!=='rabbit'){cyl(.42,.42,.06,c.shirt,0,1.34,0,g);cyl(.26,.3,.16,c.shirt,0,1.44,0,g)}box(.5,.42,.2,0xd28c51,0,.65,-.29,g);box(.52,.08,.22,0xe5b27c,0,.87,-.29,g);return g}
function makeFire(){const g=group(1.4,0,1.4);for(let i=0;i<9;i++)rock(Math.cos(i/9*Math.PI*2)*.7,Math.sin(i/9*Math.PI*2)*.7,.17,g);for(let i=0;i<3;i++){const l=cyl(.1,.13,1.15,0x8c6549,0,.15,0,g,7);l.rotation.z=Math.PI/2;l.rotation.y=i*Math.PI/3}for(let i=0;i<6;i++){const f=cone(.17+Math.random()*.15,.5+Math.random()*.5,i%2?0xffb954:0xec8149,Math.cos(i)*.2,.5,Math.sin(i)*.2,g,7);flames.push(f)}const light=new THREE.PointLight(0xffa34a,5,8);light.position.set(0,1,0);g.add(light);return g}
function makeMeal(){const g=group(-1.4,0,2.4);box(1.5,.12,1,0xc99c6a,0,.7,0,g);for(const x of [-.55,.55])for(const z of [-.32,.32])box(.08,.65,.08,0x876d4f,x,.34,z,g);cyl(.29,.29,.03,0xf8ebcc,0,.79,0,g);const food=activeVisit?.mealMenu||'curry';if(food==='sandwich'){const bread=box(.38,.11,.3,0xe8be78,0,.87,0,g);bread.rotation.y=.4}else if(food==='bbq'){for(let i=0;i<3;i++)ball(.09,i===1?0x78925f:0x9d684b,(i-1)*.12,.87,0,g)}else if(food==='rice'){cone(.19,.27,0xf5f0d7,0,.91,0,g,3);box(.12,.12,.1,0x3f5d4d,0,.85,.14,g)}else{ball(.19,food==='stew'?0xf3dfac:food==='noodles'?0xd9bb77:0xc49b53,0,.83,0,g);ball(.08,0x8fa765,.12,.89,0,g)}cyl(.11,.09,.2,0x6d8d80,.48,.85,.1,g);box(.8,.09,.65,0xc79c6b,0,.35,1.05,g);for(const x of [-.28,.28])box(.06,.33,.06,0x886c4b,x,.17,1.05,g);return g}
function makeCamp(){camera=campCamera;clearWorld();scene.fog.near=65;scene.fog.far=140;const c=camps[selected];if(c.land==='sea'){scene.background.set(0xc8e0e5);scene.fog.color.set(0xc8e0e5);scene.fog.near=110;scene.fog.far=420;}const land=cyl(CAMP_RADIUS,CAMP_RADIUS+.3,1.3,c.color,0,-.7,0,root,12);land.userData.seasonGround=c.color;cyl(CAMP_RADIUS+.3,CAMP_RADIUS-.4,.35,0xb7aa86,0,-1.52,0,root,12);if(c.land!=='sea')cyl(70,70,.1,0xe4ead8,0,-1.8,0,root,64);path([[0,16],[0,13],[0,10],[0,8]],1.4,0xdcca9f);gate=group(-4,0,15);for(const x of [-1.5,1.5])box(.2,2,.2,0xa58860,x,1,0,gate);box(3.6,.55,.2,0xb69a6e,0,2.1,0,gate);const tx=textSprite('WELCOME CAMP','#fff9df',.38,gate);tx.position.set(0,2.12,.15);sign('CAMP SITE  ←',-11,11);for(let i=0;i<28;i++){let a=i/28*Math.PI*2;let x=Math.cos(a)*16,z=Math.sin(a)*15;if(z>5&&Math.abs(x)<3)continue;if(!allowsPerimeterTree(c.land,x,z))continue;tree(x,z,.75+(i%4)*.18,['fuji','play','meadow','farm'].includes(c.land)?1:i%3===0?1:0)}if(c.id==='fumoto'){fuji(0,-19,.95);for(let i=0;i<9;i++)tree(-15+i*3.5,-17,.7,0);}if(c.land==='cabins'){cabin(-12,-8,1.25);cabin(12,-9,1.1);playset(13,2);pondShape([[3,-1],[5,-2],[6,-1],[6,0],[4,1],[3,0]],0x9dcac6);fuji(1,-20,.85)}if(c.id==='verga'){pondShape([[-8,-8],[-6,-7],[-7,-4],[-6,0],[-7,4],[-6,8],[-8,9],[-9,4],[-8,0],[-9,-4]],0x94c5bf);for(let i=0;i<13;i++)rock(-6.5+Math.sin(i)*.6,-7+i*1.2,.3);cabin(12,-7,1);for(let i=0;i<10;i++)tree(-13+i*3,-15,1.1)}if(c.id==='mochiya'){fuji(2,-19,.95);playset(-13,-6,1.4);playset(13,0,.85);const slide=box(1,.15,2.4,0xd6a16a,-12,1,-10);slide.rotation.x=.5;box(1,1.5,1,0xb9a075,-12,.75,-11);}for(let i=0;i<18;i++)flower(-12+(i%6)*.5,(c.land==='sea'?7:-9)+Math.floor(i/6)*.5);const sceneryStart=root.children.length;addLandscape(c);const scenery=group();for(const object of root.children.slice(sceneryStart)){if(object!==scenery)scenery.add(object)}scenery.scale.set(1.55,1,1.55);tentGroup=shelter(-2,0,1.55,root,activeVisit.tentType||'dome');tentGroup.rotation.y=.18;fireGroup=makeFire();mealGroup=makeMeal();character=makeBear(activeVisit.character||profile.character);moveTarget.copy(character.position);sleepText=textSprite('z Z z','#ecedc9',.65);sleepText.position.set(-2,2.6,0);sleepText.visible=false;const sg=new THREE.BufferGeometry();let pos=[];for(let i=0;i<280;i++)pos.push((Math.random()-.5)*110,8+Math.random()*17,-80);sg.setAttribute('position',new THREE.Float32BufferAttribute(pos,3));stars=new THREE.Points(sg,new THREE.PointsMaterial({color:0xfff5cd,size:.2,transparent:true,depthWrite:false,fog:false}));campCamera.add(stars);stars.visible=false;cloud(-10,13,-12,2);cloud(10,11,-10,1.7);yaw=.4;pitch=.72;dist=46;wantedDist=46;camTarget.set(-.6,0,1);if(innerWidth<600){dist=51;wantedDist=51;camTarget.set(0,0,2)}setupPlaceables();spawnCompanions();lastPlayerInput=clock.elapsedTime;campEnvironment=new CampEnvironment(root,material);updateScene();campCamera.position.set(camTarget.x+Math.sin(yaw)*Math.cos(pitch)*dist,camTarget.y+Math.sin(pitch)*dist,camTarget.z+Math.cos(yaw)*Math.cos(pitch)*dist);campCamera.lookAt(camTarget);}
function addLandscape(c){if(['highland','mountain'].includes(c.land)){for(let i=0;i<5;i++)cone(2.6,3+i%3,0x8b9e7f,-8+i*4,1.4,-9,root,7);if(c.land==='mountain')for(let i=0;i<5;i++){const g=tree(-6+i*3,-5,1,1);g.children[0].material=material(0xdadbc3)}}if(['genshi','river'].includes(c.land)&&c.id!=='verga'){pondShape([[-8,-8],[-6,-8],[-6,0],[-7,4],[-6,8],[-8,9],[-9,3],[-8,-2]],0x94c5bf);for(let i=0;i<12;i++)rock(-6.6+Math.sin(i)*.5,-7+i*1.2,.3)}if(c.land==='genshi'){for(const [x,z] of [[-5,-5],[4,-4]]){const hut=group(x,0,z);const roof=tent(0,0,1.6,hut,0xb89b65);box(1.5,.5,1.6,0xa88f64,0,.25,0,hut);rod([-.7,2.2,0],[.7,2.5,0],.07,0x807054,hut)}}if(['lakefuji','highlake'].includes(c.land)){pondShape([[-9,-7],[-4,-8],[1,-7],[5,-8],[8,-5],[7,-2],[1,-3],[-4,-2],[-9,-4]],0x9ccac7);if(c.land==='lakefuji')fuji(1,-10,1);else for(let i=0;i<4;i++)cone(3,3+i%2,0x8a9e7f,-7+i*4,1.5,-10,root,7)}if(c.land==='forest'){cabin(-8.5,-7,1.3);cabin(8.5,-8,1);cone(5,4,0x8b9987,0,2,-10,root,9);for(let i=0;i<8;i++)tree(-7+i*2,-7,1.25)}if(c.land==='sea'){
// An open ocean extends beyond the fog, hiding the far edge of the land disk.
const shoreline=Array.from({length:81},(_,i)=>{const x=-240+i*6;return [x,coastZ(x)]});
const oceanGeometry=new THREE.BufferGeometry();oceanGeometry.setAttribute('position',new THREE.Float32BufferAttribute(oceanVertices(),3));oceanGeometry.computeVertexNormals();const ocean=mesh(oceanGeometry,0x91c5ce);ocean.userData.layer=-1;
const sand=pondShape([...shoreline,...shoreline.map(([x,z])=>[x,z+1.15]).reverse()],0xe5d4ac,.13);sand.userData.layer=-1;
for(let row=0;row<5;row++){const wave=shoreline.filter(([x])=>Math.abs(x)<70).map(([x,z])=>[x,z-2-row*3]);const foam=pondShape([...wave,...wave.map(([x,z])=>[x,z-.06]).reverse()],0xd6e9df,.15);foam.userData.layer=-1;}
}if(['farm','meadow'].includes(c.land)){for(let i=0;i<8;i++){box(.12,.8,.12,0xcbb48b,-7+i*2,.4,-5);if(i<7)box(2,.09,.1,0xcbb48b,-6+i*2,.55,-5)}for(let i=0;i<5;i++){const hill=ball(3,0x9caf7d,-8+i*4,-.3,-10,root,8);hill.scale.y=.4}if(c.land==='farm'){const barn=cabin(5,-5,1.3);for(let i=0;i<3;i++){const g=group(-5+i*1.5,0,-4);const body=ball(.43,0xf0e9d8,0,.5,0,g);body.scale.set(1.4,.85,.8);ball(.22,0x777764,.5,.6,0,g);for(const x of [-.3,.3])rod([x,0,-.2],[x,.4,-.2],.04,0x807b65,g)}}}}
function openCampScene(){mapGesture.reset();dragging=false;setMapMenu(false);setCampPanel(null);mode=viewingPast?'replay':'game';$('.gameHint').textContent=viewingPast?'ドラッグで景色を見渡す ・ 記録は変更されません':'ドラッグで景色を見渡す · 地面をクリックして移動 · 矢印キー / WASDでも歩けます';renderer.domElement.setAttribute('aria-label','ドラッグで景色を見渡せる3Dキャンプ場');$('#sceneTag').textContent=viewingPast?'◷ 過去のキャンプを表示中':'⌖ キャンプ場の入口';$('#mapUI').hidden=true;$('#gameUI').hidden=false;$('#mapNav').classList.remove('active');$('#mapPins').innerHTML='';const c=camps[selected];$('#locationRegion').textContent=c.region+' / '+c.en;$('#locationName').textContent=c.name;$('#locationDesc').textContent=viewingPast?`${dateLabel(activeVisit)}の思い出。表示しても訪問回数や体験内容は変わりません。`:c.desc;makeCamp();renderTasks();$('#arrangeBtn').hidden=viewingPast;document.querySelectorAll('[data-camp-panel=actions],[data-camp-panel=placement]').forEach(b=>b.hidden=viewingPast);}
function enterCamp(resume=false){if(busy||selected<0)return;if(mode==='map')rememberMapView();const c=camps[selected],pending=saved._active;let setup;if(!resume){try{setup=tripSetupSnapshot(getStartDraft(c));}catch(e){toast(e.message);return;}}let found=resume&&pending?.campId===c.id?saved[c.id].visits.find(v=>v.id===pending.visitId&&!v.closed):null;if(!found){if(pending){const old=saved[pending.campId]?.visits.find(v=>v.id===pending.visitId);if(old)old.closed=true}found={id:newId(),startedAt:new Date().toISOString(),visitDate:setup?.visitDate||todayInJapan(),actions:{},tentType:profile.preferredTent,character:profile.character,companions:setup?.companions||structuredClone(profile.companions),weather:setup?.weather||'sunny',mealMenu:null,closed:false};saved[c.id].visits.push(found);saved._active={campId:c.id,visitId:found.id}}activeVisit=found;startDraft=null;viewingPast=false;save();openCampScene();if(!resume)startEntrance();toast(`${c.short}へようこそ。今日は自由にそとあそび！`)}
function openPastVisit(campId,visitId){if(busy){toast('体験が終わってから、思い出を開けます。');return}const c=camps.find(c=>c.id===campId),v=saved[campId]?.visits.find(v=>v.id===visitId);if(!c||!v)return;const snapshot=replaySnapshot(v);if(mode==='map')rememberMapView();if(mode==='game')closeVisit();selected=camps.indexOf(c);activeVisit=snapshot;viewingPast=true;if($('#modal').open)$('#modal').close();openCampScene();toast(dateLabel(snapshot)+'のキャンプを表示しています。')}

function applyEnvironment(){if(!activeVisit||!campEnvironment)return;const config=campEnvironment.apply(activeVisit,camps[selected].land);scene.background.set(night?0x536775:config.sky);scene.fog.color.copy(scene.background);ambient.intensity=night?.9:config.ambient;sun.intensity=night?.5:config.sun;if(stars){stars.visible=night;stars.material.opacity=activeVisit.weather==='rainy'?.5:1;}clouds.forEach(c=>c.visible=false);$('#gameUI').dataset.season=config.season;$('#gameUI').dataset.weather=activeVisit.weather||'unknown';$('#memoryDetails').textContent=config.summary+(activeVisit.actions.meal?' ・ '+(MEALS[activeVisit.mealMenu]?.name||'キャンプごはん'):'');const label=$('#environmentSummary');if(label)label.textContent=config.summary;campEnvironment.update(clock.elapsedTime,night,matchMedia('(prefers-reduced-motion: reduce)').matches);}
function setNight(value){if(!value)wakeShelterParty();night=value;if(value&&activeVisit?.actions.tent&&activeVisit?.actions.sleep)journeyActors().forEach(a=>a.visible=false);document.body.classList.toggle('night',value);applyEnvironment();if(soundOn)updateAudio();}
function updateScene(){const s=activeVisit.actions;carGroup.visible=!!s.car;tarpGroup.visible=!!s.tarp;tentGroup.visible=!!s.tent;mealGroup.visible=!!s.meal;const asleep=viewingPast&&!!s.sleep;fireGroup.visible=!!s.fire&&!asleep;sleepText.visible=asleep;setNight(asleep);character.rotation.z=asleep?Math.PI/2:0;if(viewingPast){const home=normalizePlacement(activeVisit.layout?.tent,'tent');sleepText.position.x=home.x;sleepText.position.z=home.z;character.position.set(home.x,asleep?.12:0,home.z+(asleep?.4:2.5));moveTarget.copy(character.position)}}
function renderTasks(){renderPlacementPanel();const c=camps[selected],n=actions.filter(a=>activeVisit.actions[a[0]]).length,s=activeVisit.actions;$('#taskCount').textContent=viewingPast?'思い出を表示中':n?'✓ クリア':'自由に体験';$('#weatherControl').hidden=viewingPast;$('#currentWeather').value=activeVisit.weather||'unknown';$('#memoryDetails').textContent=environmentForVisit(activeVisit,camps[selected].land).summary+(activeVisit.actions.meal?' ・ '+(MEALS[activeVisit.mealMenu]?.name||'キャンプごはん'):'');$('#visitLabel').textContent=viewingPast?`${dateLabel(activeVisit)} ・ 過去のキャンプ`:`今回：${visits(c).length+(n?0:1)}回目のキャンプ`;$('#visitDateControl').hidden=viewingPast;$('#currentVisitDate').max=todayInJapan();$('#currentVisitDate').value=visitDateOf(activeVisit);$('#tasks').innerHTML=actions.map(a=>`<div class="task ${s[a[0]]?'done':''}"><i>${s[a[0]]?'✓':a[1]}</i>${a[0]==='tent'&&s.tent?(shelterTypes[activeVisit.tentType]||'ロッジ型')+'で設営':a[0]==='meal'&&s.meal?(MEALS[activeVisit.mealMenu]?.name||'ごはんをたべる'):a[2]}<small>${s[a[0]]?'体験済み':viewingPast?'未体験':'自由に選択'}</small></div>`).join('');$('#progressBar').style.width=n?'100%':'0%';$('#journalNote').textContent=viewingPast?'この訪問で実施した体験だけを再現しています。新しいキャンプは地図に戻って始められます。':n?'この訪問はクリア！ 続けて遊んでも、次の場所へ行ってもOK。':'どれか1つ楽しむだけでクリア。テントなしの焚き火やお昼寝もOK！';$('#actionDock').innerHTML=viewingPast?`<div class="replayBanner"><span>◷ ${dateLabel(activeVisit)} の思い出</span><strong>${actions.filter(a=>s[a[0]]).map(a=>a[1]+' '+(a[0]==='tent'?(shelterTypes[activeVisit.tentType]||'ロッジ型'):a[2])).join('　')}</strong><small>ドラッグで景色を見渡せます ・ 記録は変更されません</small></div>`:actions.map(a=>`<button class="action ${s[a[0]]?'done':''}" data-action="${a[0]}" ${busy?'disabled':''}><span class="icon">${a[1]}</span><strong>${a[2]}</strong><small>${s[a[0]]?(a[0]==='tent'?'種類を変える':PLACEABLE_KEYS.includes(a[0])?'場所を変える':'もう一度楽しむ'):a[3]}</small></button>`).join('')+(viewingPast?'':`<button class="action returnAction" data-action="return" ${busy?'disabled':''}><span class="icon">🏡</span><strong>帰る</strong><small>片付けて出発</small></button>`);document.querySelectorAll('[data-action]').forEach(b=>b.onclick=()=>b.dataset.action==='return'?leaveCamp():b.dataset.action==='tent'?chooseShelter():b.dataset.action==='meal'?chooseMeal():activeVisit.actions[b.dataset.action]&&PLACEABLE_KEYS.includes(b.dataset.action)?startPlacement(b.dataset.action):doAction(b.dataset.action));$('#navCount').textContent=camps.filter(c=>count(c)>0).length+'/'+camps.length;$('#finishVisit').textContent=viewingPast?'思い出を閉じて地図へ':n?'✓ キャンプを終えて地図へ':'体験せず地図へもどる';$('#replayDaylight').hidden=!viewingPast;$('#replayDaylight').textContent=night?'☀ 昼の景色を見る':'🌙 夜の景色を見る';}

let animAction=null;
async function doAction(id,tentType,mealMenu){if(busy||!activeVisit||viewingPast)return;finishPlacement();setCampPanel(null);playerIdle=null;lastPlayerInput=clock.elapsedTime;const wasClear=actions.some(a=>activeVisit.actions[a[0]]);busy=true;
 if(id==='meal'){activeVisit.mealMenu=mealMenu||'curry';root.remove(mealGroup);mealGroup=makeMeal();placeableGroups.set('meal',mealGroup);applyPlacement('meal');mealGroup.visible=false;}
 partyActivity=null;if(night){setNight(false);sleepText.visible=false;character.rotation.z=0;character.position.y=0}
 if(id==='car'){await arriveByCar();activeVisit.actions.car=true;busy=false;lastPlayerInput=clock.elapsedTime;save();renderTasks();$('#sceneTag').textContent='🚙 駐車完了。みんなでそとあそび！';toast('✓ 車をとめて、みんなで到着しました。');return;}
 if(id==='tent'){activeVisit.tentType=tentType||'dome';root.remove(tentGroup);tentGroup=shelter(-2,0,1.55,root,activeVisit.tentType);placeableGroups.set('tent',tentGroup);applyPlacement('tent');tentGroup.visible=false}
 renderTasks();const home=normalizePlacement(activeVisit.layout?.tent,'tent'),location=PLACEABLE_KEYS.includes(id)?normalizePlacement(activeVisit.layout?.[id],id):home;
 const dest=[location.x,0,location.z+1.5];moveTarget.set(...dest);$('#sceneTag').textContent=({tent:'⛺ 自分だけの基地を準備中…',fire:'🔥 薪を組んで、火を灯そう…',meal:'🍳 あつあつのごはん、できあがり。',sleep:'🌙 おやすみの準備…',car:'🚙 車をとめています…',tarp:'⛱️ タープをひろげよう…'})[id];
 const spots=partyPositions(location.x,location.z,companions.length);partyActivity={id,x:location.x,z:location.z,phase:'gather',until:Infinity};companions.forEach((c,i)=>{c.target.set(spots[i].x,0,spots[i].z);c.idle=null;});const journey=Math.max(character.position.distanceTo(moveTarget),...companions.map(c=>c.actor.position.distanceTo(c.target)),0);await new Promise(r=>setTimeout(r,Math.min(4500,Math.max(700,journey/5*1000))));character.position.set(...dest);companions.forEach(c=>c.actor.position.copy(c.target));partyActivity.phase='together';animAction={id,start:clock.getElapsedTime()};await new Promise(r=>setTimeout(r,1400));activeVisit.actions[id]=true;character.position.set(...dest);moveTarget.copy(character.position);
 if(PLACEABLE_KEYS.includes(id))placeableGroups.get(id).visible=true;
 if(id==='sleep'){if(activeVisit.actions.tent)await enterSleepingShelter();setNight(true);fireGroup.visible=false;sleepText.visible=true;sleepText.position.set(home.x,2.7,home.z);character.position.set(home.x,.12,home.z+.4);character.rotation.z=Math.PI/2;moveTarget.copy(character.position)}
 partyActivity.until=id==='sleep'?Infinity:clock.elapsedTime+5;busy=false;lastPlayerInput=clock.elapsedTime;save();renderTasks();$('#sceneTag').textContent=({tent:`⛺ ${shelterTypes[activeVisit.tentType]}の基地ができました`,fire:'🔥 ぱちぱち。あたたかいね',meal:'🍳 おそとで食べると、おいしいね',sleep:'🌙 おやすみなさい',car:'🚙 お気に入りの車でキャンプ',tarp:'⛱️ 木かげのリビングができました'})[id];
 toast(wasClear?'✓ 思い出を記録しました。':`✦ キャンプ場クリア！ ${camps[selected].short}・${visits(camps[selected]).length}回目の思い出`);
}
function closeVisit(){if(activeVisit&&!viewingPast){activeVisit.closed=true;if(!actions.some(a=>activeVisit.actions[a[0]]))saved[camps[selected].id].visits=saved[camps[selected].id].visits.filter(v=>v!==activeVisit);delete saved._active;activeVisit=null;save()}}
function goMap(){if(campJourney?.kind==='enter'){campJourney=null;busy=false;}if(busy){toast('入退場・体験の演出が終わるまで少しお待ちください。');return}mapGesture.reset();dragging=false;finishPlacement();setCampPanel(null);if(!viewingPast)closeVisit();activeVisit=null;viewingPast=false;mode='map';renderer.domElement.setAttribute('aria-label','ドラッグで移動できる3Dキャンプ地図');$('#mapUI').hidden=false;$('#gameUI').hidden=true;$('#mapNav').classList.add('active');makeMap();if(soundOn)updateAudio()}

function showModal(html,wide=false){$('#modal').classList.toggle('wide',wide);$('#modalContent').innerHTML=html;if(!$('#modal').open)$('#modal').showModal()}
function showRecords(){showModal(`<div class="eyebrow">CAMPING PASSPORT</div><h2>旅と、そとあそびの記録。</h2><p>${camps.filter(c=>count(c)>0).length} / ${camps.length} か所クリア ・ 合計 ${camps.reduce((n,c)=>n+visits(c).length,0)} 回のキャンプ<br>1つでも体験した訪問を1回と数えます。各体験の数字は、その体験をした訪問の数です。</p><div class="tableScroll"><table class="recordsTable"><thead><tr><th>キャンプ場</th><th>訪問</th>${actions.map(a=>`<th>${a[1]}<small>${a[0]==='tent'?'設営':a[2].replace('をする','').replace('をたべる','')}</small></th>`).join('')}<th>訪問ごと</th></tr></thead><tbody>${camps.filter(c=>visits(c).length).map(c=>`<tr><td><strong>${count(c)?'✓ ':''}${c.short}</strong><small>${c.region}</small></td><td><b>${visits(c).length}</b> 回</td>${actions.map(a=>`<td class="${did(c,a[0])?'achieved':'notyet'}">${did(c,a[0])?'✓ '+visits(c).filter(v=>v.actions[a[0]]).length:'—'}</td>`).join('')}<td><button class="historyBtn" data-history="${camps.indexOf(c)}">履歴 →</button></td></tr>`).join('')}</tbody></table>${camps.some(c=>visits(c).length)?'':'<p class="emptyRecords">まだ訪問の記録がありません。地図から最初のキャンプへ出かけよう。</p>'}</div><p class="fineprint">${saveFailed?'このブラウザでは保存できません。':'訪問と道具の配置はサーバーに自動保存されます。'} ゲーム内の訪問記録です。</p>`,true);document.querySelectorAll('[data-history]').forEach(b=>b.onclick=()=>showHistory(+b.dataset.history))}
function showHistory(i){const c=camps[i],list=sortVisits(visits(c));showModal(`<button class="textBack" id="recordsBack">← すべての記録へ</button><div class="eyebrow">${c.pref} / VISIT HISTORY</div><h2>${c.name}</h2><p>${list.length}回のキャンプ ・ 体験したこと ${count(c)}種類</p><button class="secondary" id="addPastFromHistory">＋ 過去のキャンプを登録</button><div class="visitHistory">${list.length?list.map((v,j)=>`<article class="visitCard"><div><b>${j+1}回目</b><time>${dateLabel(v)}</time>${!v.closed?'<span class="ongoing">滞在中</span>':''}</div><div class="historyActivities">${actions.map(a=>`<span class="${v.actions[a[0]]?'earned':'notyet'}">${a[1]} ${v.actions[a[0]]?(a[0]==='tent'?shelterTypes[v.tentType]||'ロッジ型':a[0]==='meal'?MEALS[v.mealMenu]?.name||'キャンプごはん':a[2]):'未体験'}</span>`).join('')}</div><p class="visitWeather">${WEATHER[v.weather]||WEATHER.unknown} ・ ${CHARACTERS[v.character||'bear']?.name||'コモ'}${v.companions?.length?' ・ 同行：'+v.companions.map(p=>esc(p.name)).join('、'):''}</p><div class="visitTools"><button data-preview-visit="${v.id}">◷ この様子を3Dで見る</button><button data-edit-visit="${v.id}">日付・天気などを編集</button></div>${v.legacy?'<small>更新前の体験をまとめた記録です。訪問日を登録できます。</small>':''}</article>`).join(''):'<p>まだ体験の記録がありません。過去の訪問を登録するか、新しいキャンプに出かけよう。</p>'}</div>`,true);$('#recordsBack').onclick=showRecords;$('#addPastFromHistory').onclick=()=>showVisitForm(c.id);document.querySelectorAll('[data-preview-visit]').forEach(b=>b.onclick=()=>openPastVisit(c.id,b.dataset.previewVisit));document.querySelectorAll('[data-edit-visit]').forEach(b=>b.onclick=()=>showVisitForm(c.id,b.dataset.editVisit))}
function showVisitForm(campId,visitId=null){const c=camps.find(c=>c.id===campId),v=visitId?saved[campId].visits.find(v=>v.id===visitId):null;if(!c||(visitId&&!v))return;showModal(`<div class="eyebrow">${v?'EDIT VISIT DATE':'ADD A CAMP MEMORY'}</div><h2>${v?'キャンプ記録を編集':'過去のキャンプを登録'}</h2><p>${c.name}</p><form id="visitForm"><label class="fieldLabel">訪問日<input id="recordVisitDate" type="date" required min="0001-01-01" max="${todayInJapan()}" value="${v?visitDateOf(v):todayInJapan()}"></label><label class="fieldLabel">天気<select id="recordWeather">${weatherOptions(v?.weather||'unknown')}</select></label><label class="fieldLabel">食事メニュー<select id="recordMeal"><option value="">未記録</option>${mealOptions(v?.mealMenu)}</select></label>${v?'<p class="fineprint">日付・天気・メニューを編集します。訪問回数は変わりません。</p>':`<fieldset class="manualActions"><legend>体験したこと（1つ以上）</legend>${actions.map(a=>`<label><input type="checkbox" name="pastAction" value="${a[0]}"><span>${a[1]} ${a[2]}</span></label>`).join('')}</fieldset><label class="fieldLabel" id="manualShelterField" hidden>テント・宿泊場所の種類<select id="recordShelter">${orderedShelters().map(([k,v])=>`<option value="${k}">${v}</option>`).join('')}</select></label>`}<p class="formError" id="visitFormError" role="alert"></p><div class="formButtons"><button type="button" class="secondary" id="cancelVisitForm">もどる</button><button class="primary" type="submit">${v?'記録を保存':'この思い出を登録'}</button></div></form><p class="fineprint">日付は日本時間で記録します。今日より後の日付は登録できません。</p>`);if(!v)$('#recordShelter').value=profile.preferredTent;if(!v)document.querySelector('input[name="pastAction"][value="tent"]').onchange=e=>$('#manualShelterField').hidden=!e.target.checked;$('#cancelVisitForm').onclick=()=>showHistory(camps.indexOf(c));$('#visitForm').onsubmit=e=>{e.preventDefault();const date=$('#recordVisitDate').value;try{if(!isValidVisitDate(date))throw new Error('今日以前の正しい訪問日を入力してください。');if(v){v.visitDate=date;v.weather=$('#recordWeather').value;v.mealMenu=$('#recordMeal').value||null}else{const activities=Object.fromEntries([...document.querySelectorAll('input[name="pastAction"]:checked')].map(el=>[el.value,true]));saved[c.id].visits.push(createPastVisit({id:newId(),visitDate:date,activities,tentType:$('#recordShelter').value,weather:$('#recordWeather').value,mealMenu:$('#recordMeal').value||null,character:profile.character,companions:structuredClone(profile.companions)}))}save();if(mode==='map'){const old=mapSavedView;rememberMapView();makeMap();mapSavedView=old}else if(mode==='game'&&activeVisit?.id===v?.id)renderTasks();showHistory(camps.indexOf(c));toast(v?'訪問日を保存しました。':'過去のキャンプを登録しました。')}catch(error){$('#visitFormError').textContent=error.message}}}

$('#currentVisitDate').onchange=e=>{if(viewingPast||!activeVisit)return;if(!isValidVisitDate(e.target.value)){e.target.value=visitDateOf(activeVisit);toast('今日以前の正しい訪問日を選んでください。');return}activeVisit.visitDate=e.target.value;applyEnvironment();save();toast('訪問日を保存しました。')};$('#replayDaylight').onclick=()=>{if(!viewingPast)return;setNight(!night);fireGroup.visible=!!activeVisit.actions.fire&&!night;sleepText.visible=!!activeVisit.actions.sleep&&night;$('#replayDaylight').textContent=night?'☀ 昼の景色を見る':'🌙 夜の景色を見る'};$('#clearFilters').onclick=clearFilters;$('#wishlistOnly').onclick=()=>{wishOnly=!wishOnly;selected=-1;updateMap();};
$('#backBtn').onclick=goMap;$('#finishVisit').onclick=goMap;$('#mapNav').onclick=goMap;$('.brand').onclick=e=>{e.preventDefault();goMap()};$('#bookNav').onclick=showRecords;$('.close').onclick=()=>$('#modal').close();$('#modal').addEventListener('close',()=>{if(mode==='map'&&selected>=0){const container=$('#selection .campStartSetup');if(container)renderStartSetup(camps[selected],container);}});$('#modal').addEventListener('click',e=>{if(e.target===$('#modal')){const r=$('#modal').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)$('#modal').close()}});
$('#helpBtn').onclick=()=>showModal(`<div class="helpUpdate"><b>新しい旅の楽しみ方</b><p>地図はドラッグで移動。＋／−やズームスライダーで拡大・縮小し、矢印ボタンでも移動できます。属性フィルターは選んだ条件すべてに一致する場所を表示します。</p><p>キャンプ場を選ぶと、新しいキャンプ・過去の様子の3D表示・過去の訪問登録を選べます。訪問日は記録から編集でき、過去の表示では訪問回数が増えません。</p></div><div class="eyebrow">HOW TO PLAY</div><h2>今日は、好きなことだけ。</h2><p>1. 地図や県別一覧からキャンプ場を選んで入口へ。<br>2. テント・焚き火・ごはん・ねるを、好きな順で自由に体験。<br>3. どれか1つできたら、そのキャンプ場はクリア！<br>4. 地図へ戻って再訪すると、2回目・3回目の旅に。</p><p>テント・宿泊場所はドーム型、ワンポール型、ロッジ型、コテージから選べます。設営せずに焚き火や食事、お昼寝だけ楽しんでもOK。</p><p>地図には、これまで体験した道具だけが小さく登場。設営していない場所にはテントを表示しません。「キャンプの記録」で全体の体験一覧と訪問ごとの履歴を確認できます。</p><p>体験をした滞在を1回と数えます。同じ滞在中に何度体験しても訪問は1回。途中の滞在は、キャンプ場の「途中のキャンプを再開」から続けられます。</p><p>キャンプ場内ではドラッグで視点回転、スクロールで拡大・縮小。地面をクリック、または矢印キー・WASDで歩けます。♪ で環境音を切り替え。ログインすると別の端末にも記録を引き継げます。</p>`);
$('#aboutBtn').onclick=()=>showModal(`<div class="eyebrow">ABOUT THIS LITTLE WORLD</div><h2>本物の自然から、<br>小さな世界へ。</h2><p>全国83か所のキャンプ場をモチーフにした非公式の3Dゲームです。地図の海岸線にはNatural Earthの公開地理データを、都道府県の色付けには国土数値情報（行政区域・2019年、piuccio/open-data-jp-prefectures-geojson経由）を簡略化して使用しています。キャンプ場の目印は登録された緯度・経度から配置しています。地図と登録位置はゲーム向けの概略です。地形・施設配置・距離はゲーム向けにデフォルメしています。宿泊タイプはゲーム内の自由な演出で、現地の宿泊施設や利用可否とは異なります。</p><p>各地の公式施設案内を参考に、森と清流、湖と山、高原、牧場、海風の雰囲気を表現しました。</p><p class="fineprint">境界データの出典：<a href="https://github.com/piuccio/open-data-jp-prefectures-geojson" target="_blank" rel="noopener">都道府県GeoJSON</a>・<a href="vendor/PREFECTURE-NOTICE.txt" target="_blank" rel="noopener">加工とライセンスの表示</a></p><p>参考にした公式サイト</p><ul>${camps.map(c=>`<li><a href="${c.url}" target="_blank" rel="noopener">${c.name} ↗</a></li>`).join('')}</ul><p class="fineprint">現地への訪問・予約・宿泊施設の確認には、各キャンプ場の公式情報をご利用ください。</p>`);
