const raycaster=new THREE.Raycaster(),pointer=new THREE.Vector2(),groundPlane=new THREE.Plane(new THREE.Vector3(0,1,0),0);const canvas=renderer.domElement,pointers=new Map();let pinchSpan=0,pointerStart=null,layoutGesture=false,layoutBefore=null;
function panPixels(dx,dy){mapTransition=null;const delta=mapPanDelta(mapCamera,dx,dy,innerHeight);camTarget.x=Math.max(-170,Math.min(150,camTarget.x+delta.x));camTarget.z=Math.max(-150,Math.min(100,camTarget.z+delta.z));lastPinLayout=0}
const mapGesture=new MapGesture();
function startMapPointer(e){if(e.button!==undefined&&e.button!==0)return;e.preventDefault();mapTransition=null;mapGesture.down(e.pointerId,e.clientX,e.clientY,null);dragging=true;hoverMapCamp(null);canvas.setPointerCapture(e.pointerId);canvas.focus({preventScroll:true});}
function moveMapPointer(e){const motion=mapGesture.move(e.pointerId,e.clientX,e.clientY);if(!motion)return;e.preventDefault();if(motion.type==='pinch')applyMapZoom(dist*motion.scale,motion.anchor);panPixels(motion.dx,motion.dy);}
function endMapPointer(e){const tap=mapGesture.up(e.pointerId,e.clientX,e.clientY,e.type!=='pointerup');dragging=mapGesture.points.size>0;if(!tap)return;const hit=mapCampAt(tap.x,tap.y);if(hit!==null)selectCamp(hit);else{selected=-1;mapTransition=null;updateMap();}}
window.addEventListener('pointerdown',e=>{if(mode==='map'&&e.target.closest('#mapPins .pin,#mapClusters .clusterPin'))startMapPointer(e);},{capture:true});
