for(const event of ['gesturestart','gesturechange','gestureend'])window.addEventListener(event,e=>e.preventDefault(),{passive:false});
window.addEventListener('touchmove',e=>{if(e.touches.length>1)e.preventDefault();},{passive:false});
canvas.addEventListener('pointerdown',e=>{if(mode==='map'){startMapPointer(e);return;}lastPlayerInput=clock.elapsedTime;playerIdle=null;pointers.set(e.pointerId,{x:e.clientX,y:e.clientY});dragging=true;moved=false;last={x:e.clientX,y:e.clientY};pointerStart={...last};canvas.setPointerCapture(e.pointerId);canvas.focus({preventScroll:true});if(mode==='game'&&!busy&&pointers.size===1){const key=pickPlaceable(e);if(key)startPlacement(key);layoutGesture=!!placementId;layoutBefore=placementId?{...activeVisit.layout[placementId]}:null;}if(pointers.size===2){const ps=[...pointers.values()];pinchSpan=Math.hypot(ps[1].x-ps[0].x,ps[1].y-ps[0].y);moved=true}});
canvas.addEventListener('pointermove',e=>{if(mode==='map'){moveMapPointer(e);return;}if(!pointers.has(e.pointerId))return;pointers.set(e.pointerId,{x:e.clientX,y:e.clientY});const dx=e.clientX-last.x,dy=e.clientY-last.y;if(pointerStart&&Math.hypot(e.clientX-pointerStart.x,e.clientY-pointerStart.y)>4)moved=true;if(mode==='game'&&layoutGesture&&placementId){if(moved){const p=groundAt(e);if(p)movePlacement(p.x,p.z,false)}}else{yaw-=dx*.006;pitch=Math.max(.32,Math.min(1.12,pitch+dy*.004))}last={x:e.clientX,y:e.clientY}});
function endPointer(e){if(mode==='map'){endMapPointer(e);return;}pointers.delete(e.pointerId);pinchSpan=0;dragging=pointers.size>0;if(pointers.size)last=[...pointers.values()][0];
 if(mode==='game'&&layoutGesture&&placementId){if(e.type==='pointercancel'){if(layoutBefore){activeVisit.layout[placementId]=layoutBefore;applyPlacement(placementId)}}else{const p=groundAt(e);if(p&&moved)movePlacement(p.x,p.z,true);else if(p&&!pickPlaceable(e))movePlacement(p.x,p.z,true);}layoutGesture=false;return;}

 if(e.type==='pointerup'&&!moved&&mode==='game'&&!busy&&!night){const p=groundAt(e);if(p&&Math.hypot(p.x,p.z)<WALK_RADIUS){lastPlayerInput=clock.elapsedTime;playerIdle=null;moveTarget.set(p.x,0,p.z);$('#sceneTag').textContent='⌖ 相棒と、おさんぽ'}}
}
canvas.addEventListener('pointerup',endPointer);canvas.addEventListener('pointercancel',endPointer);window.addEventListener('wheel',e=>{if(e.ctrlKey)e.preventDefault();if($('#modal').open||e.target.closest('header,.intro,#selection,.mapTools,.mapSwitcher,footer,#placementPanel,#placementMiniBar,#campMenuBar,.journal,#actionDock'))return;e.preventDefault();if(mode==='map')applyMapZoom(wheelMapDistance(dist,e.deltaY,e.deltaMode,innerHeight),{x:e.clientX,y:e.clientY});else wantedDist=Math.max(20,Math.min(95,wantedDist*Math.exp(e.deltaY*.0015)))},{passive:false});
const keys={};window.addEventListener('keydown',e=>{const target=e.target;if(e.key==='Escape'&&!$('#modal').open){setMapMenu(false);setCampPanel(null);if(mode==='map'){selected=-1;mapTransition=null;updateMap()}else finishPlacement();return}if($('#modal').open||target.closest('input,select,textarea,button,[role="scrollbar"],#campList'))return;if(['ArrowUp','ArrowDown','ArrowLeft','ArrowRight','w','a','s','d'].includes(e.key)){e.preventDefault();if(mode==='map'){const dx=(['d','ArrowRight'].includes(e.key)?1:0)-(['a','ArrowLeft'].includes(e.key)?1:0),dz=(['s','ArrowDown'].includes(e.key)?1:0)-(['w','ArrowUp'].includes(e.key)?1:0);panMap(dx,dz)}else if(mode==='game'&&!placementId){lastPlayerInput=clock.elapsedTime;playerIdle=null;keys[e.key]=true}}});window.addEventListener('keyup',e=>keys[e.key]=false);window.addEventListener('blur',()=>{Object.keys(keys).forEach(k=>keys[k]=false);pointers.clear();mapGesture.reset();dragging=false;if(layoutGesture&&placementId&&layoutBefore){activeVisit.layout[placementId]=layoutBefore;applyPlacement(placementId)}layoutGesture=false});
$('#mapZoom').oninput=e=>setZoom(e.target.value);$('#zoomIn').onclick=()=>setZoom(zoomForDistance(wantedDist)+10);$('#zoomOut').onclick=()=>setZoom(zoomForDistance(wantedDist)-10);$('#mapReset').onclick=()=>setMapView(false);document.querySelectorAll('[data-pan]').forEach(b=>b.onclick=()=>{const [x,z]=b.dataset.pan.split(',').map(Number);panMap(x,z)});
let audioCtx,noiseSource,noiseGain,filter;
function updateAudio(){if(!audioCtx)return;noiseGain.gain.setTargetAtTime(soundOn?(night?.025:.045):0,audioCtx.currentTime,.4);filter.frequency.setTargetAtTime(night?600:1300,audioCtx.currentTime,.4)}
$('#soundBtn').onclick=async()=>{try{if(!audioCtx){audioCtx=new AudioContext();const b=audioCtx.createBuffer(1,audioCtx.sampleRate*4,audioCtx.sampleRate);const d=b.getChannelData(0);let last=0;for(let i=0;i<d.length;i++){last=(last+Math.random()*.04-.02)/1.02;d[i]=last*8}noiseSource=audioCtx.createBufferSource();noiseSource.buffer=b;noiseSource.loop=true;filter=audioCtx.createBiquadFilter();filter.type='lowpass';noiseGain=audioCtx.createGain();noiseGain.gain.value=0;noiseSource.connect(filter);filter.connect(noiseGain);noiseGain.connect(audioCtx.destination);noiseSource.start()}await audioCtx.resume();soundOn=!soundOn;updateAudio();$('#soundBtn').textContent=soundOn?'♪ ON':'♪ OFF';toast(soundOn?'風と木々の音に、耳をすませて。':'環境音をオフにしました。')}catch{toast('このブラウザでは環境音を再生できません。')}};
function updateListScroll(){const list=$('#campList'),rail=$('#listRail'),thumb=$('#listThumb'),max=list.scrollHeight-list.clientHeight;const needs=max>2;rail.hidden=!needs;const h=Math.max(32,rail.clientHeight*(list.clientHeight/Math.max(1,list.scrollHeight)));thumb.style.height=h+'px';thumb.style.top=(max>0?(rail.clientHeight-h)*list.scrollTop/max:0)+'px';thumb.setAttribute('aria-valuemax',String(Math.max(0,Math.round(max))));thumb.setAttribute('aria-valuenow',String(Math.round(list.scrollTop)));$('#scrollNext').disabled=!needs||list.scrollTop>=max-2;$('#listPosition').textContent=needs?'SCROLL TO EXPLORE':'すべて表示中';$('.campListFrame').classList.toggle('atBottom',!needs||list.scrollTop>=max-2)}
$('#campList').addEventListener('scroll',updateListScroll,{passive:true});$('#scrollNext').onclick=()=>$('#campList').scrollBy({top:190,behavior:'smooth'});let scrollDrag=null;$('#listThumb').addEventListener('pointerdown',e=>{e.preventDefault();scrollDrag={y:e.clientY,top:$('#campList').scrollTop};$('#listThumb').setPointerCapture(e.pointerId)});$('#listThumb').addEventListener('pointermove',e=>{if(!scrollDrag)return;const list=$('#campList'),travel=$('#listRail').clientHeight-$('#listThumb').clientHeight;list.scrollTop=scrollDrag.top+(e.clientY-scrollDrag.y)*(list.scrollHeight-list.clientHeight)/Math.max(1,travel)});for(const event of ['pointerup','pointercancel'])$('#listThumb').addEventListener(event,()=>scrollDrag=null);$('#listThumb').addEventListener('keydown',e=>{if(['ArrowDown','ArrowUp','Home','End'].includes(e.key)){e.preventDefault();const list=$('#campList');if(e.key==='Home')list.scrollTop=0;else if(e.key==='End')list.scrollTop=list.scrollHeight;else list.scrollBy({top:e.key==='ArrowDown'?90:-90,behavior:'smooth'})}});
