let placementId=null,placementRing=null;const placeableGroups=new Map();
function makeCar(parent=root){const g=group(0,0,0,parent);box(1.6,.6,2.7,0x8b9e80,0,.64,0,g);box(1.4,.65,1.5,0xb0b99a,0,1.2,-.15,g);box(1.42,.43,.05,0xcce0d7,0,1.25,.63,g);box(1.42,.43,.05,0xb7d1ca,0,1.25,-.93,g);for(const x of [-.83,.83]){box(.035,.42,1.05,0xc4d9d0,x*.86,1.25,-.15,g);for(const z of [-.85,.85]){const wheel=cyl(.34,.34,.18,0x44534c,x,.38,z,g,12);wheel.rotation.z=Math.PI/2;(g.userData.wheels ||= []).push(wheel);const hub=cyl(.14,.14,.19,0xd5d4bd,x,.38,z,g,10);hub.rotation.z=Math.PI/2;}}for(const x of [-.53,.53]){box(.31,.16,.04,0xffedba,x,.7,1.37,g);box(.25,.13,.04,0xc97959,x,.7,-1.37,g)}box(1.65,.12,.14,0xd6d2b9,0,.42,1.38,g);const door=group(-.82,.65,.5,g);box(.05,.62,.95,0xb0b99a,0,.29,-.47,door);box(.055,.35,.7,0xc4d9d0,-.01,.55,-.45,door);g.userData.door=door;return g}
function makeTarp(parent=root){const g=group(0,0,0,parent);const points=[[-2,1.5,-1.5],[0,2.5,-1.5],[2,1.5,-1.5],[-2,1.5,1.5],[0,2.5,1.5],[2,1.5,1.5]];const geo=new THREE.BufferGeometry();geo.setAttribute('position',new THREE.Float32BufferAttribute([...points[0],...points[1],...points[3],...points[1],...points[4],...points[3],...points[1],...points[2],...points[4],...points[2],...points[5],...points[4]],3));geo.computeVertexNormals();const cloth=mesh(geo,0xd3bb89,0,0,0,g);cloth.material=new THREE.MeshStandardMaterial({color:0xd3bb89,side:THREE.DoubleSide,roughness:1});for(const z of [-1.5,1.5]){rod([0,0,z],[0,2.55,z],.04,0x8d7658,g);rod([0,2.55,z],[0,0,z*1.6],.018,0xe9d8b2,g)}for(const x of [-2,2])for(const z of [-1.5,1.5])rod([x,1.5,z],[x*1.15,0,z*1.15],.018,0xe9d8b2,g);return g}
function setupPlaceables(){activeVisit.layout=normalizeLayout(activeVisit.layout);carGroup=makeCar();tarpGroup=makeTarp();for(const [key,g] of Object.entries({tent:tentGroup,fire:fireGroup,meal:mealGroup,car:carGroup,tarp:tarpGroup})){placeableGroups.set(key,g);applyPlacement(key)}placementRing=mesh(new THREE.RingGeometry(1.25,1.35,48),0xe4965a,0,.08,0);placementRing.rotation.x=-Math.PI/2;placementRing.material=new THREE.MeshBasicMaterial({color:0xe4965a,side:THREE.DoubleSide,transparent:true,opacity:.85,depthWrite:false});placementRing.visible=false;}
function applyPlacement(key){const p=normalizePlacement(activeVisit?.layout?.[key],key),g=placeableGroups.get(key);if(!p||!g)return;g.position.set(p.x,0,p.z);g.rotation.y=p.rotation;if(placementRing&&placementId===key)placementRing.position.set(p.x,.08,p.z);}
function groundAt(e){pointer.set(e.clientX/innerWidth*2-1,-e.clientY/innerHeight*2+1);camera.updateMatrixWorld();raycaster.setFromCamera(pointer,camera);const p=new THREE.Vector3();return raycaster.ray.intersectPlane(groundPlane,p)?p:null;}
function pickPlaceable(e){if(mode!=='game'||busy||viewingPast)return null;groundAt(e);root.updateMatrixWorld(true);const groups=[...placeableGroups.entries()].filter(([,g])=>g.visible);const hit=raycaster.intersectObjects(groups.map(([,g])=>g),true)[0];if(!hit)return null;let o=hit.object;while(o&&o!==root){const entry=groups.find(([,g])=>g===o);if(entry)return entry[0];o=o.parent}return null;}
function startPlacement(key){if(busy||viewingPast||mode!=='game'||!activeVisit.actions[key])return;setCampPanel('placement');placementId=key;document.body.classList.add('placement-compact');$('#placementMiniName').textContent=(actions.find(a=>a[0]===key)?.[1]||'')+' '+({tent:'テント',fire:'焚き火',meal:'ごはん',car:'車',tarp:'タープ'})[key]+'を配置';if(night){partyActivity=null;}if(night){setNight(false);sleepText.visible=false;character.rotation.z=0;fireGroup.visible=!!activeVisit.actions.fire;}applyPlacement(key);placementRing.visible=true;canvas.classList.add('placing');$('#placementPanel').hidden=false;renderPlacementPanel();}
function finishPlacement(){document.body.classList.remove('placement-compact');placementId=null;if(placementRing)placementRing.visible=false;renderer.domElement.classList.remove('placing');$('#placementPanel').hidden=true;}
function movePlacement(x,z,commit=true){if(!placementId||!activeVisit||viewingPast)return;activeVisit.layout[placementId]=normalizePlacement({...activeVisit.layout[placementId],x,z},placementId);applyPlacement(placementId);if(commit){save();$('#placementMessage').textContent='✓ 配置を自動保存しました。続けて動かせます。';}}
function renderPlacementPanel(){if(!$('#placementItems')||!activeVisit)return;$('#placementItems').innerHTML=actions.filter(a=>PLACEABLE_KEYS.includes(a[0])).map(a=>`<button data-place="${a[0]}" aria-pressed="${placementId===a[0]}" ${activeVisit.actions[a[0]]?'':'disabled'}>${a[1]} ${a[0]==='tent'?'テント':a[0]==='fire'?'焚き火':a[0]==='meal'?'ごはん':a[0]==='car'?'車':'タープ'}</button>`).join('');document.querySelectorAll('[data-place]').forEach(b=>b.onclick=()=>startPlacement(b.dataset.place));$('#placementMessage').textContent=placementId?'地面をクリック、または道具をドラッグして配置。':'置いた道具を選んで、好きな場所に動かそう。';document.querySelectorAll('[data-nudge],[data-turn]').forEach(b=>b.disabled=!placementId);}
$('#arrangeBtn').onclick=()=>{if(busy||viewingPast)return;if(!$('#placementPanel').hidden){finishPlacement();return}$('#placementPanel').hidden=false;renderPlacementPanel()};$('#placementDone').onclick=()=>{finishPlacement();setCampPanel(null)};
