function getStartDraft(c){if(startDraft?.campId!==c.id)startDraft={campId:c.id,...newTripSetup(profile)};return startDraft;}
function renderStartSetup(c,container){const draft=getStartDraft(c);container.innerHTML=`<div class="tripSetupFields"><label>訪問日<input type="date" data-setup-date aria-label="開始するキャンプの訪問日" max="${todayInJapan()}" value="${draft.visitDate}" required></label><label>天気<select data-setup-weather aria-label="開始するキャンプの天気">${weatherOptions(draft.weather)}</select></label></div><div class="tripParty"><span>同行者</span><div class="tripPartyChips">${draft.companions.map((c,i)=>`<button type="button" data-trip-person="${i}" aria-pressed="${c.enabled}">${CHARACTERS[c.person.character].icon} ${esc(c.person.name)} ${c.enabled?'✓':''}</button>`).join('')||'<small>ひとりでキャンプ</small>'}<button type="button" data-trip-add ${draft.companions.filter(c=>c.enabled).length>=5?'disabled':''}>＋ 追加</button></div></div><div class="tripAddPerson" hidden><input data-trip-name maxlength="30" placeholder="同行者の名前" aria-label="今回追加する同行者の名前"><select data-trip-character aria-label="今回追加する同行者のキャラクター">${Object.entries(CHARACTERS).map(([id,p])=>`<option value="${id}">${p.icon} ${p.name}</option>`).join('')}</select><button type="button" data-trip-confirm>追加</button></div>`;container.querySelector('[data-setup-date]').onchange=e=>draft.visitDate=e.target.value;container.querySelector('[data-setup-weather]').onchange=e=>draft.weather=e.target.value;container.querySelectorAll('[data-trip-person]').forEach(b=>b.onclick=()=>{draft.companions[+b.dataset.tripPerson].enabled=!draft.companions[+b.dataset.tripPerson].enabled;renderStartSetup(c,container);});container.querySelector('[data-trip-add]').onclick=()=>{container.querySelector('.tripAddPerson').hidden=false;container.querySelector('[data-trip-name]').focus();};container.querySelector('[data-trip-confirm]').onclick=()=>{const name=container.querySelector('[data-trip-name]').value.trim();if(!name){container.querySelector('[data-trip-name]').focus();return;}const member={enabled:true,person:{name,relation:'家族',character:container.querySelector('[data-trip-character]').value}},unused=draft.companions.findIndex(c=>!c.enabled);if(draft.companions.length>=5&&unused>=0)draft.companions[unused]=member;else if(draft.companions.length<5)draft.companions.push(member);renderStartSetup(c,container);};}
function toggleWishlist(c){saved[c.id].wishlist=!saved[c.id].wishlist;saved[c.id].wishlistUpdatedAt=new Date().toISOString();save();updateMap();toast(saved[c.id].wishlist?'♥ 行きたいキャンプ場に追加しました。':'行きたいチェックを外しました。');}
function wakeShelterParty(){if(!character||!activeVisit)return;const actors=journeyActors(),home=normalizePlacement(activeVisit.layout?.tent,'tent'),spots=partyPositions(home.x,home.z,actors.length);actors.forEach((a,i)=>{if(!a.visible){a.position.set(spots[i].x,0,spots[i].z);a.rotation.z=0;a.visible=true;}});companions.forEach(c=>c.target.copy(c.actor.position));moveTarget.copy(character.position);}
function updateShelterEntry(t){const entry=sleepEntry;if(!entry)return;entry.actors.forEach((a,i)=>{const pose=sampleShelterEntry(entry.starts[i],entry.home,i,t-entry.start);a.visible=!pose.inside;a.position.set(pose.x,Math.sin(t*12+i)*.035,pose.z);const door=shelterDoor(entry.home);a.rotation.y=Math.atan2(door.x-entry.starts[i].x,door.z-entry.starts[i].z);a.rotation.z=0;});moveTarget.copy(character.position);}
async function enterSleepingShelter(){const actors=journeyActors();sleepEntry={actors,starts:actors.map(a=>({x:a.position.x,z:a.position.z})),home:normalizePlacement(activeVisit.layout?.tent,'tent'),start:clock.elapsedTime};$('#sceneTag').textContent='⛺ みんなでテントに入って、おやすみなさい';await new Promise(r=>setTimeout(r,2400));updateShelterEntry(sleepEntry.start+3);actors.forEach(a=>a.visible=false);sleepEntry=null;}

function journeyActors(){return [character,...companions.map(c=>c.actor)];}
function startEntrance(){busy=true;playerIdle=null;partyActivity=null;const actors=journeyActors(),ends=entrancePositions(actors.length);campJourney={kind:'enter',start:clock.elapsedTime,actors,starts:actors.map((a,i)=>({x:(i%2?1:-1)*.65,z:19+Math.floor(i/2)*1.2})),ends,view:{target:camTarget.clone(),distance:wantedDist}};camTarget.set(0,0,10);wantedDist=56;$('#sceneTag').textContent='👣 入口に、みんなで到着';updateJourney(clock.elapsedTime);renderTasks();}
function leaveCamp(){if(busy||viewingPast||mode!=='game')return;finishPlacement();setCampPanel(null);busy=true;setNight(false);sleepText.visible=false;playerIdle=null;partyActivity=null;const actors=journeyActors(),hasCar=!!activeVisit.actions.car,destination=normalizePlacement(activeVisit.layout?.car,'car');actors.forEach(a=>{a.visible=true;a.rotation.z=0;});campJourney={kind:'exit',start:clock.elapsedTime,actors,starts:actors.map(a=>({x:a.position.x,z:a.position.z})),ends:actors.map((a,i)=>hasCar?carDoorPoint(destination,i):({x:(i%2?1:-1)*.65,z:19+Math.floor(i/2)*.8})),hasCar,destination,packSpots:partyPositions(normalizePlacement(activeVisit.layout?.tent,'tent').x,normalizePlacement(activeVisit.layout?.tent,'tent').z,actors.length),gear:[tentGroup,tarpGroup,mealGroup,fireGroup].filter(g=>g.visible).map(g=>({g,scale:g.scale.clone()}))};camTarget.set(hasCar?destination.x*.3:0,0,7);wantedDist=58;$('#sceneTag').textContent='🧺 みんなで道具を片付けています…';renderTasks();}
function updateJourney(t){const j=campJourney;if(!j)return;const elapsed=t-j.start,pose=journeyPose(j.kind,elapsed,j.hasCar);for(const [i,a] of j.actors.entries()){const packing=j.kind==='exit'&&pose.phase==='pack',start=j.kind==='exit'&&!packing?j.packSpots[i]:j.starts[i],end=packing?j.packSpots[i]:j.ends[i],u=packing?Math.min(1,elapsed/1.8):pose.progress;a.visible=!pose.boarded;a.rotation.z=0;a.position.set(start.x+(end.x-start.x)*u,Math.sin(t*12+i)*.04,end.z===start.z?start.z:start.z+(end.z-start.z)*u);a.rotation.y=Math.atan2(end.x-start.x,end.z-start.z);poseIdle(a,pose.phase==='pack'?'wave':null,t+i,i?companions[i-1].scale:1.25);}
 if(j.kind==='exit'){if(j.hasCar&&carGroup.userData.door)carGroup.userData.door.rotation.y=pose.phase==='walk'?Math.sin(pose.progress*Math.PI)*1.1:0;for(const [i,{g,scale}] of j.gear.entries()){const u=Math.max(0,Math.min(1,(elapsed-.6-i*.35)/1.3));g.scale.copy(scale).multiplyScalar(1-u);if(u===1)g.visible=false;}if(pose.phase==='walk')$('#sceneTag').textContent=j.hasCar?'🚙 道具を積んで、みんなで車に乗ります…':'👣 片付け完了。入口へ向かいます';if(pose.phase==='drive'){const car=sampleCarArrival(j.destination,DRIVE_SECONDS*(1-pose.driveProgress));carGroup.position.set(car.x,0,car.z);carGroup.rotation.y=car.rotation+Math.PI;carGroup.userData.wheels?.forEach(w=>w.rotation.x=-elapsed*9);$('#sceneTag').textContent='🚙 また来ようね。入口から出発！';}}
 moveTarget.copy(character.position);if(!pose.done)return;campJourney=null;busy=false;lastPlayerInput=t;if(j.kind==='enter'){companions.forEach((c,i)=>{c.next=t+3.5+i*.2;c.idle='look';});j.actors.forEach((a,i)=>a.position.set(j.ends[i].x,0,j.ends[i].z));companions.forEach(c=>c.target.copy(c.actor.position));moveTarget.copy(character.position);camTarget.copy(j.view.target);wantedDist=j.view.distance;$('#sceneTag').textContent='⌖ 入口に到着！ 好きな場所へ歩こう';renderTasks();}else{closeVisit();mode='leaving';goMap();toast('道具を片付けて帰りました。思い出は記録に残ります。');}}

function spawnCompanions(){for(const c of companions)root.remove(c.actor);companions=[];const party=normalizeCompanions(activeVisit?.companions);for(const [i,person] of party.entries()){const actor=makeBear(person.character),scale=person.relation==='子ども'?.9:1.12;actor.scale.setScalar(scale);actor.position.set(-3+i*1.5,0,4+i%2);const label=textSprite(person.name,'#42674b',.32,actor);label.position.set(0,2.05,0);companions.push({actor,person,scale,target:actor.position.clone(),idle:null,next:clock.elapsedTime+.25+i*.18});}const summary=$('#partySummary');if(summary)summary.textContent=party.length?'いっしょに：'+party.map(p=>CHARACTERS[p.character].icon+' '+p.name).join(' ・ '):'ひとりで、のんびりキャンプ';}
function poseIdle(actor,action,t,scale){for(const [i,arm] of (actor.userData.arms||[]).entries()){arm.position.y=.6;arm.position.x=(i?1:-1)*.4;if(action==='wave'&&i===1){arm.position.y=1.05+Math.sin(t*8)*.12;arm.position.x=.5}if(action==='stretch'){arm.position.y=.9;arm.position.x=(i?1:-1)*.52;}}if(action==='hop')actor.position.y+=Math.max(0,Math.sin(t*5))*.35;if(action==='look')actor.rotation.y+=Math.sin(t*2)*.012;if(action==='sit'){actor.position.y=-.12;actor.scale.y=scale*.82;}else actor.scale.y=scale;}
function idleDestination(energetic=false){let choice=chooseIdle(Math.random,{energetic});for(let i=0;i<16;i++){if(!PLACEABLE_KEYS.some(k=>activeVisit.actions[k]&&Math.hypot(choice.x-(activeVisit.layout?.[k]?.x??DEFAULT_LAYOUT[k].x),choice.z-(activeVisit.layout?.[k]?.z??DEFAULT_LAYOUT[k].z))<(k==='tarp'?3:2)))break;choice=chooseIdle(Math.random,{energetic});}return choice;}
function updateCampLife(dt,t){if(sleepEntry){updateShelterEntry(t);return;}if(campJourney){updateJourney(t);return;}if(carArrival){updateCarArrival(t);return;}if(partyActivity&&clock.elapsedTime>partyActivity.until)partyActivity=null;const paused=busy||!!partyActivity||dragging||!!placementId||$('#modal').open;if(mode==='game'&&!night&&!paused&&t-lastPlayerInput>2.2&&moveTarget.distanceTo(character.position)<.2){if(!playerIdle||t>playerIdle.until){const choice=idleDestination();playerIdle={action:choice.action,until:t+choice.duration};if(choice.action==='walk')moveTarget.set(choice.x,0,choice.z);}}else if(paused||t-lastPlayerInput<=2.2||night)playerIdle=null;
 for(const [i,c] of companions.entries()){const a=c.actor;if(partyActivity){a.rotation.z=night&&partyActivity.id==='sleep'?Math.PI/2:0;const delta=c.target.clone().sub(a.position);delta.y=0;const len=delta.length();if(len>.06){a.position.add(delta.normalize().multiplyScalar(Math.min(len,dt*5)));a.rotation.y=Math.atan2(delta.x,delta.z);a.position.y=Math.sin(t*12+i)*.04;}else{a.position.y=night?.15:0;a.rotation.y=Math.atan2(partyActivity.x-a.position.x,partyActivity.z-a.position.z);poseIdle(a,partyActivity.phase==='together'?(partyActivity.id==='tent'||partyActivity.id==='tarp'?'wave':partyActivity.id==='sleep'?null:'sit'):null,t+i,c.scale);}continue;}if(night){a.rotation.z=Math.PI/2;a.position.y=.15;continue;}a.rotation.z=0;if(paused){a.position.y=0;poseIdle(a,null,t,c.scale);continue;}if(t>c.next&&c.target.distanceTo(a.position)<.2){const choice=idleDestination(true);c.idle=choice.action;c.next=t+choice.duration;const follow=mode==='game'&&t-lastPlayerInput<2.8;if(follow){c.target.set(Math.max(-5,Math.min(7,character.position.x+Math.cos(i*2.4)*2)),0,Math.max(2,Math.min(11,character.position.z+Math.sin(i*2.4)*2)));c.idle='walk';}else if(choice.action==='walk')c.target.set(choice.x,0,choice.z);else c.target.copy(a.position).setY(0);}const delta=c.target.clone().sub(a.position);delta.y=0;const len=delta.length();if(len>.08){a.position.add(delta.normalize().multiplyScalar(Math.min(len,dt*(c.person.relation==='子ども'?3.8:3.2))));a.rotation.y=Math.atan2(delta.x,delta.z);a.position.y=Math.sin(t*12+i)*.045;}else a.position.y=Math.sin(t*2+i)*.018;poseIdle(a,len>.08?'walk':c.idle,t+i,c.scale);}
}

function setMapMenu(open){document.body.classList.toggle('map-menu-open',open);$('#mapMenuToggle').setAttribute('aria-expanded',String(open));requestAnimationFrame(updateListScroll);}
function closeActivityChoice(){document.body.dataset.actionChoice='';$('#activityChoices').hidden=true;$('#activityChoices').innerHTML='';$('#campPanelTitle').textContent='今日のそとあそび';}
function setCampPanel(panel){if(busy&&panel)return;if(panel!=='actions')closeActivityChoice();document.body.classList.remove('placement-compact');if(panel!=='placement'&&typeof placementId!=='undefined')finishPlacement();document.body.dataset.campPanel=panel||'';$('#campPanelTitle').textContent=({actions:'今日のそとあそび',placement:'道具の配置',journal:'キャンプの記録',view:'視点と環境音'})[panel]||'';document.querySelectorAll('[data-camp-panel]').forEach(b=>b.setAttribute('aria-expanded',String(b.dataset.campPanel===panel)));if(panel==='placement'){$('#placementPanel').hidden=false;renderPlacementPanel();}}
for(const el of [$('.journal'),$('#actionDock'),$('#placementPanel'),$('.viewControls')])$('#campPanels').appendChild(el);
$('#mapMenuToggle').onclick=()=>setMapMenu(!document.body.classList.contains('map-menu-open'));
$('#closeCampPanel').onclick=()=>setCampPanel(null);$('#placementChoose').onclick=()=>setCampPanel('placement');$('#placementMiniDone').onclick=()=>{finishPlacement();setCampPanel(null)};
document.querySelectorAll('[data-camp-panel]').forEach(b=>b.onclick=()=>setCampPanel(document.body.dataset.campPanel===b.dataset.campPanel&&!document.body.classList.contains('placement-compact')?null:b.dataset.campPanel));

persist();makeMap();animate();updateAccountStatus();if(cloudDirty)flushCloud();addEventListener('pagehide',()=>{if(cloudDirty&&account.canSave)fetch('/api/account',{method:'PUT',headers:{'Content-Type':'application/json','X-Camp-Storage':account.storageId},body:JSON.stringify({profile,records:saved,revision:cloudRevision}),keepalive:true}).catch(()=>{});});if(catalogOffline)toast('キャンプ場情報は端末のサンプルを表示しています。');setInterval(refreshCloud,60000);addEventListener('focus',refreshCloud);addEventListener('online',()=>{if(!account.canSave){location.reload();return}flushCloud();refreshCloud()});

function orderedShelters(){return Object.entries(shelterTypes).sort(([a],[b])=>Number(b===profile.preferredTent)-Number(a===profile.preferredTent))}
function weatherOptions(value){return Object.entries(WEATHER).map(([k,label])=>`<option value="${k}" ${k===value?'selected':''}>${label}</option>`).join('')}
function mealOptions(value){return Object.entries(MEALS).map(([k,m])=>`<option value="${k}" ${k===value?'selected':''}>${m.icon} ${m.name}</option>`).join('')}
function chooseMeal(){if(busy||viewingPast)return;setCampPanel('actions');document.body.dataset.actionChoice='meal';$('#campPanelTitle').textContent='今日の食事';$('#activityChoices').hidden=false;$('#activityChoices').innerHTML=`<button class="choiceBack" id="backToActivities">← 体験一覧</button><div class="activityChoiceGrid mealChoices">${Object.entries(MEALS).map(([id,m])=>`<button data-meal="${id}"><span>${m.icon}</span><strong>${m.name}</strong></button>`).join('')}</div>`;$('#backToActivities').onclick=closeActivityChoice;document.querySelectorAll('[data-meal]').forEach(b=>b.onclick=()=>doAction('meal',null,b.dataset.meal));}
function renderAttributeButtons(){$('#attributeFilters').innerHTML=ATTRIBUTE_LABELS.map(a=>`<button data-attribute="${a}" aria-pressed="${activeAttributes.includes(a)}" class="${activeAttributes.includes(a)?'selected':''}">${a}</button>`).join('');document.querySelectorAll('[data-attribute]').forEach(b=>b.onclick=()=>{const a=b.dataset.attribute;activeAttributes=activeAttributes.includes(a)?activeAttributes.filter(x=>x!==a):[...activeAttributes,a];$('#campList').scrollTop=0;updateMap();setMapView(false)})}
function showProfile(){showModal(`<div class="eyebrow">YOUR CAMPING ID</div><h2>旅人のプロフィール</h2><p>旅の記録はサーバーに自動保存されます。保存ボタンの操作は必要ありません。</p><div class="autoSaveNotice"><span id="profileSaveState">${$('#syncState').textContent}</span><small>${account.user?'ログイン中のアカウントで、ほかの端末からも続きを楽しめます。':'ログインなしでも記録されます。ほかの端末でも遊ぶときはログインしてください。'}</small></div><form id="profileForm"><label class="fieldLabel">旅人の名前<input id="profileName" maxlength="30" required placeholder="例：こもれび" value="${esc(profile.name)}"></label><fieldset class="characterField"><legend>旅の相棒をえらぶ</legend><div class="characterGrid">${Object.entries(CHARACTERS).map(([id,c])=>`<label><input type="radio" name="character" value="${id}" ${profile.character===id?'checked':''}><span><b>${c.icon}</b><strong>${c.name}</strong></span></label>`).join('')}</div></fieldset><label class="fieldLabel">いつものテント<select id="preferredTent">${Object.entries(shelterTypes).map(([id,n])=>`<option value="${id}" ${profile.preferredTent===id?'selected':''}>${n}</option>`).join('')}</select><small>次の設営で、このタイプを先頭に表示します。</small></label><fieldset class="companionField"><legend>同行者・家族</legend><p class="fineprint">最大5人。名前とキャラクターを選ぶと一緒に遊びます。現在のキャンプと、これからの訪問に反映します。</p><div id="companionRows"></div><button type="button" class="secondary" id="addCompanion">＋ 同行者を追加</button></fieldset><button class="primary" type="submit">設定を終える →</button></form><div class="accountPanel">${account.user?'<a class="authLink" id="signoutLink" href="/signout-with-chatgpt?return_to=%2Fcamp%2F" target="_top">ログアウト →</a>':'<a class="primary authLink" id="signinLink" href="/signin-with-chatgpt?return_to=%2Fcamp%2F" target="_top">ログインして、旅を持ち歩く →</a><p class="fineprint">ログインすると、今の旅の記録をアカウントへ自動で引き継ぎます。未ログインの記録を開くには、このブラウザのCookieを残してください。</p>'}</div>`);
 let companionDraft=structuredClone(profile.companions);
 const updateProfile=()=>{const name=$('#profileName').value.trim();if(!name)return;const next=normalizeProfile({name,character:document.querySelector('input[name="character"]:checked').value,preferredTent:$('#preferredTent').value,companions:companionDraft});if(JSON.stringify(next)!==JSON.stringify(profile)){profile=next;startDraft=null;save()}};
 const renderCompanionForm=()=>{ $('#companionRows').innerHTML=companionDraft.map((c,i)=>`<div class="companionRow"><label>名前<input data-companion-name="${i}" aria-label="同行者${i+1}の名前" maxlength="30" value="${esc(c.name)}"></label><label>関係<select data-companion-relation="${i}" aria-label="同行者${i+1}の関係">${COMPANION_RELATIONS.map(v=>`<option ${c.relation===v?'selected':''}>${v}</option>`).join('')}</select></label><label>キャラクター<select data-companion-character="${i}" aria-label="同行者${i+1}のキャラクター">${Object.entries(CHARACTERS).map(([id,c2])=>`<option value="${id}" ${id===c.character?'selected':''}>${c2.icon} ${c2.name}</option>`).join('')}</select></label><button type="button" data-remove-companion="${i}" aria-label="同行者${i+1}を外す">外す</button></div>`).join('');$('#addCompanion').disabled=companionDraft.length>=5;document.querySelectorAll('[data-companion-name]').forEach(el=>el.oninput=()=>{companionDraft[+el.dataset.companionName].name=el.value;updateProfile()});document.querySelectorAll('[data-companion-relation],[data-companion-character]').forEach(el=>el.onchange=()=>{const isCharacter=el.dataset.companionCharacter!==undefined;companionDraft[+(isCharacter?el.dataset.companionCharacter:el.dataset.companionRelation)][isCharacter?'character':'relation']=el.value;updateProfile()});document.querySelectorAll('[data-remove-companion]').forEach(el=>el.onclick=()=>{companionDraft.splice(+el.dataset.removeCompanion,1);updateProfile();renderCompanionForm()});};$('#addCompanion').onclick=()=>{companionDraft.push({name:'同行者'+(companionDraft.length+1),relation:'家族',character:['rabbit','fox','panda','bear'][companionDraft.length%4]});updateProfile();renderCompanionForm()};renderCompanionForm();
 $('#profileName').oninput=updateProfile;$('#preferredTent').onchange=updateProfile;document.querySelectorAll('input[name="character"]').forEach(el=>el.onchange=updateProfile);$('#profileForm').onsubmit=e=>{e.preventDefault();updateProfile();$('#modal').close()};
 for(const id of ['signinLink','signoutLink'])if($('#'+id))$('#'+id).onclick=async e=>{const link=e.currentTarget;if(link.dataset.ready)return;updateProfile();if(!cloudDirty&&!cloudSaving)return;e.preventDefault();await flushCloud();if(cloudDirty||cloudSaving){toast('自動保存が完了してからログインを切り替えられます。接続をご確認ください。');return}link.dataset.ready='true';link.click()};
}
$('#accountBtn').onclick=showProfile;
$('#currentWeather').innerHTML=weatherOptions('unknown');$('#currentWeather').onchange=e=>{if(viewingPast||!activeVisit)return;activeVisit.weather=e.target.value;applyEnvironment();save();renderTasks();toast('天気を記録しました。')};
